using System;
using System.IO;
using System.Linq;
using MassiveArmy.Industrial;
static class MiningWorkflowChecks {
    static FramePose Point(double x,double z=0)=>new FramePose{body=1,y=100000,x=x,z=z};
    static IndustrialMachine Machine(IndustrialWorld w,string type,double x,double z=0){var m=new IndustrialMachine{id=w.AllocateId(),owner=1,definition=type,recipe=IndustrialCatalog.Machines[type].recipe,pose=Point(x,z),input=new Inventory{capacity=IndustrialCatalog.Machines[type].capacity},output=new Inventory{capacity=100000}};w.machines.Add(m);return m;}
    static IndustrialCommand Assign(IndustrialWorld w,IndustrialMachine vehicle,long source,long destination,string role,IndustrialAuthority authority=null){var actor=w.Actor(1);actor.pose=vehicle.pose;actor.pose.z+=9;var c=IndustrialHaulNavigation.Plan(w,1,vehicle.id,source,destination,null,out var error,false,role);if(c==null)throw new Exception("Mining route: "+error);c.sequence=actor.lastSequence+1;c.operationRole=role;c.definition=role=="tailings"?null:"auto-source";c.item=w.creativeMode?"creative-vehicle":"vehicle-operation";var result=authority==null?w.Execute(1,c):authority.Execute(1,c);if(!result.accepted)throw new Exception(result.message);actor.pose=Point(-1000,-1000);return c;}
    public static void Run(Action<bool,string> Check){
        var crew=new IndustrialWorld{creativeMode=true};crew.Register(1,Point(-1000,-1000));crew.EnableMiningWorkflow();var digger=Machine(crew,"excavator",0,-7);var truck=Machine(crew,"truck",-20,-20);var store=Machine(crew,"store",300);store.input.capacity=100000;var node=new SurfaceDeposit{id=crew.AllocateId(),pose=Point(0),remaining=new MaterialLot{litres=1000,iron=250,copper=100,radioactive=25,activity=123}};crew.deposits.Add(node);
        Assign(crew,digger,node.id,store.id,"excavate");Assign(crew,truck,node.id,store.id,"transport");for(int n=0;n<75;n++)crew.Step();Check(digger.pose.Distance(node.pose)<8&&node.remaining.litres<1000&&truck.input.bulk.litres>0,"Excavator stays at the finite node and bucket-loads a nearby dump truck");Check(node.remaining.litres+digger.input.bulk.litres+truck.input.bulk.litres+store.input.bulk.litres==1000,"Digging and truck loading conserve every litre during handoff");var resumed=IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(crew));for(int n=0;n<2000;n++){crew.Step();resumed.Step();}Check(store.input.bulk.litres==1000&&store.input.bulk.iron==250&&store.input.bulk.copper==100&&store.input.bulk.radioactive==25&&store.input.bulk.activity==123,"Truck delivers the excavator's real grade and activity without mining extra material");Check(resumed.Machine(store.id).input.bulk.litres==1000&&resumed.Machine(store.id).input.bulk.activity==123&&resumed.Machine(digger.id).haul.role=="excavate"&&resumed.Machine(truck.id).haul.role=="transport","Mining-team roles and in-progress bucket handoffs survive save/load");Check(digger.pose.Distance(node.pose)<8&&digger.input.bulk.litres==0,"Primary excavator remains at its worksite after the truck leaves");
        var refiningPower=Machine(crew,"generator",306,8.5);refiningPower.input.capacity=100000;refiningPower.input.Add("fuel",1000);var refiningWash=Machine(crew,"sluice",306);refiningWash.water=1000;refiningWash.powerSource=refiningPower.id;var refiningFoundry=Machine(crew,"foundry",312);refiningFoundry.powerSource=refiningPower.id;var refiningPress=Machine(crew,"press",318);refiningPress.powerSource=refiningPower.id;var componentStore=Machine(crew,"store",324);crew.Actor(1).pose=Point(303,3);var feed=crew.Execute(1,new IndustrialCommand{kind="bulk-transfer",sequence=crew.Actor(1).lastSequence+1,source=store.id,target=refiningWash.id,count=1000});if(!feed.accepted)throw new Exception(feed.message);void Belt(IndustrialMachine from,IndustrialMachine to,string filter){crew.Actor(1).pose=Point((from.pose.x+to.pose.x)*.5);var c=new IndustrialCommand{kind="belt",sequence=crew.Actor(1).lastSequence+1,source=from.id,target=to.id,item=filter};var result=crew.Execute(1,c);if(!result.accepted)throw new Exception(result.message);}Belt(refiningWash,refiningFoundry,"iron-ore");Belt(refiningFoundry,refiningPress,"iron-bar");Belt(refiningPress,componentStore,"plate");for(int n=0;n<3500;n++)crew.Step();Check(componentStore.input.Count("plate")>0&&IndustrialWorld.TailingsCount(refiningWash.frontTailings)>0&&refiningWash.output.Count("tailings")==0,"Excavator-loaded truck material still becomes manufactured components while waste stays at the front chute");
        var waiting=new IndustrialWorld{creativeMode=true};waiting.Register(1,Point(-1000));waiting.EnableMiningWorkflow();var loneTruck=Machine(waiting,"truck",0);var sink=Machine(waiting,"store",60);var untouched=new SurfaceDeposit{id=waiting.AllocateId(),pose=Point(30),remaining=new MaterialLot{litres=100,iron=20}};waiting.deposits.Add(untouched);Assign(waiting,loneTruck,untouched.id,sink.id,"transport");for(int n=0;n<300;n++)waiting.Step();Check(untouched.remaining.litres==100&&loneTruck.input.bulk.litres==0&&loneTruck.haul.waitingForExcavator,"A transport truck waits for a loader and cannot mine the node by itself");
        var interrupted=new IndustrialWorld{creativeMode=true};interrupted.Register(1,Point(-1000));interrupted.EnableMiningWorkflow();var pausedDigger=Machine(interrupted,"excavator",0,-7);var partialTruck=Machine(interrupted,"truck",-20,-20);var sharedSink=Machine(interrupted,"store",300);sharedSink.input.capacity=2000;var partialNode=new SurfaceDeposit{id=interrupted.AllocateId(),pose=Point(0),remaining=new MaterialLot{litres=1000,iron=200}};interrupted.deposits.Add(partialNode);Assign(interrupted,pausedDigger,partialNode.id,sharedSink.id,"excavate");Assign(interrupted,partialTruck,partialNode.id,sharedSink.id,"transport");for(int n=0;n<500&&partialTruck.input.bulk.litres==0;n++)interrupted.Step();pausedDigger.enabled=false;for(int n=0;n<30;n++)interrupted.Step();Check(partialTruck.haul.phase==2&&partialTruck.input.bulk.litres>0&&partialTruck.haul.reserved==partialTruck.input.bulk.litres&&sharedSink.input.reserved==partialTruck.input.bulk.litres,"An interrupted bucket load departs partially and releases unused delivery reservations");
        var waste=new IndustrialWorld{creativeMode=true};waste.Register(1,Point(-1000,-1000));var power=Machine(waste,"generator",-30,-30);power.input.capacity=100000;power.input.Add("fuel",1000);var sluice=Machine(waste,"sluice",0);sluice.powerSource=power.id;sluice.water=10000;sluice.input.bulk=new MaterialLot{litres=2000,iron=400,radioactive=200,activity=700};var cleaner=Machine(waste,"loader",15,-15);string path=Path.GetFullPath("TestResults/Industrial/mining-waste-"+Guid.NewGuid().ToString("N")+".xml");long dumpId;
        using(var auth=new IndustrialAuthority(waste,path)){auth.Save();auth.EnableMiningWorkflow();Check(auth.CreateTailingsDump(sluice.id,Point(40))==null,"A validated tailings dump is created away from the sluice");dumpId=sluice.tailingsDump;Assign(waste,cleaner,sluice.id,dumpId,"tailings",auth);auth.Step(1000);auth.Step(500);}
        var dump=waste.Pile(dumpId);Check(sluice.output.Count("tailings")==0&&sluice.output.Count("radioactive-tailings")==0&&sluice.output.Count("iron-ore")==400&&sluice.output.Count("radioactive-ore")==200,"Sluice sends ore to conveyors and discharges waste at the front instead of item output");Check(dump.Volume==1400&&dump.material.litres==0&&dump.cells.Sum()==1400&&IndustrialWorld.TailingsCount(sluice.frontTailings)==0,"Periodic cleanup empties the front heap into a visibly growing separate dump pile");double totalActivity=sluice.output.items.Sum(i=>i.activity)+IndustrialWorld.TailingsActivity(sluice.frontTailings)+dump.Activity+IndustrialWorld.TailingsActivity(cleaner.input);Check(Math.Abs(totalActivity-700)<1e-8,"Radioactive tailings preserve activity through washing, loading and dumping");var recovered=IndustrialAuthority.Load(path);Check(recovered.miningWorkflow&&recovered.Pile(dumpId).Volume==1400&&recovered.Machine(cleaner.id).haul.role=="tailings"&&recovered.Machine(sluice.id).tailingsDump==dumpId,"Crash replay restores the workflow migration, waste site, roles and completed deliveries once");
        sluice.enabled=false;sluice.frontTailings=new Inventory{capacity=IndustrialWorld.FrontTailingsCapacity};sluice.frontTailings.Add("tailings",100,0);cleaner.pose=cleaner.haul.route[cleaner.haul.pickupIndex];cleaner.haul.phase=1;cleaner.haul.waypoint=cleaner.haul.pickupIndex;cleaner.haul.lastServiceTick=waste.tick;long dumpBefore=dump.Volume;for(int n=0;n<30;n++)waste.Step();Check(IndustrialWorld.TailingsCount(sluice.frontTailings)==100&&IndustrialWorld.TailingsCount(cleaner.input)==0,"Cleanup waits for a batch instead of shuttling every small spill");for(int n=0;n<600;n++)waste.Step();Check(dump.Volume==dumpBefore+100&&IndustrialWorld.TailingsCount(sluice.frontTailings)==0,"The cleanup timer eventually collects a small final batch");
        sluice.enabled=true;sluice.frontTailings.Add("tailings",IndustrialWorld.FrontTailingsCapacity,0);sluice.input.bulk=new MaterialLot{litres=10,iron=2};long waterBefore=sluice.water;cleaner.enabled=false;waste.Step();Check(sluice.input.bulk.litres==10&&sluice.water==waterBefore&&sluice.status.Contains("heap full"),"A full front heap stops washing before consuming dirt or water");
        waste.Actor(1).pose=cleaner.pose;var forbiddenSource=new SurfaceDeposit{id=waste.AllocateId(),pose=Point(40,-30),remaining=new MaterialLot{litres=100,iron=20}};waste.deposits.Add(forbiddenSource);var badRole=new IndustrialCommand{sequence=waste.Actor(1).lastSequence+1,kind="haul-start",source=forbiddenSource.id,target=cleaner.id,count=dumpId,operationRole="haul"};var mixed=waste.Execute(1,badRole);Check(!mixed.accepted&&mixed.message.Contains("Keep tailings")&&forbiddenSource.remaining.litres==100,"Waste dumps reject pay dirt without consuming its resources");waste.Actor(1).pose=dump.pose;waste.Step();Check(waste.Actor(1).exposure>0&&dump.Activity>0,"The relocated radioactive dump remains a radiation source");
        var dischargePoint=IndustrialWorld.TailingsPose(sluice);dischargePoint.y+=1;Check(waste.FrontDischargeObstruction(dischargePoint,.4)!=null,"New conveyor and utility routes reserve the front heap space before it grows");dischargePoint.y+=3;Check(waste.FrontDischargeObstruction(dischargePoint,.4)==null,"Connections can route above the reserved tailings mound");
        var old=new IndustrialWorld();old.Register(1,Point(0));var oldSluice=Machine(old,"sluice",0);oldSluice.output.Add("radioactive-tailings",700,13.5);old.EnableMiningWorkflow();Check(oldSluice.output.Count("radioactive-tailings")==0&&IndustrialWorld.TailingsCount(oldSluice.frontTailings)==700&&IndustrialWorld.TailingsActivity(oldSluice.frontTailings)==13.5,"Existing sluice waste migrates to the front without deleting or laundering its activity");
        var moving=new IndustrialWorld{creativeMode=true};moving.Register(1,Point(-1000));moving.EnableMiningWorkflow();var arriving=Machine(moving,"excavator",0,-20);var approaching=Machine(moving,"truck",-20,-20);var destination=Machine(moving,"store",100);destination.input.capacity=100000;var movingNode=new SurfaceDeposit{id=moving.AllocateId(),pose=Point(0),remaining=new MaterialLot{litres=500,iron=100}};moving.deposits.Add(movingNode);Assign(moving,arriving,movingNode.id,destination.id,"excavate");Assign(moving,approaching,movingNode.id,destination.id,"transport");Check(moving.ActiveMiningSites(1,approaching.pose).Contains(movingNode.id)&&moving.ActiveMiningSites(2,approaching.pose).Count==0,"Transport discovery prefers owned active mining worksites");approaching.enabled=false;for(int n=0;n<150;n++)moving.Step();approaching.enabled=true;for(int n=0;n<1500;n++)moving.Step();Check(destination.input.bulk.litres==500&&approaching.haul.blockedTicks==0,"Truck routes planned before excavator arrival leave its future loading berth clear");
        var overflow=new IndustrialWorld();overflow.Register(1,Point(0));var oldOverflow=Machine(overflow,"sluice",0);oldOverflow.output.Add("radioactive-tailings",6000,42);overflow.EnableMiningWorkflow();Check(IndustrialWorld.TailingsCount(oldOverflow.frontTailings)==5000&&oldOverflow.output.Count("radioactive-tailings")==1000&&Math.Abs(IndustrialWorld.TailingsActivity(oldOverflow.frontTailings)+oldOverflow.output.items.Sum(i=>i.activity)-42)<1e-8,"Migrating more than the front heap capacity keeps the remaining legacy waste and hazard accounted for");
        var dismantle=new IndustrialWorld();dismantle.Register(1,Point(0));dismantle.EnableMiningWorkflow();var wasteOnly=Machine(dismantle,"sluice",0);wasteOnly.frontTailings=new Inventory{capacity=5000};wasteOnly.frontTailings.Add("radioactive-tailings",50,12.5);var packWaste=dismantle.Execute(1,new IndustrialCommand{kind="pack",sequence=1,target=wasteOnly.id});Check(!packWaste.accepted&&IndustrialWorld.TailingsCount(wasteOnly.frontTailings)==50,"Dismantling cannot delete a front tailings heap or its radioactive contents");var recoverWaste=dismantle.Execute(1,new IndustrialCommand{kind="recover-tailings",sequence=2,source=wasteOnly.id,count=50});Check(recoverWaste.accepted&&dismantle.Actor(1).inventory.Count("radioactive-tailings")==50&&dismantle.Actor(1).inventory.ActivityOf("radioactive-tailings",50)==12.5,"Manual front-heap recovery preserves waste quantity and radiation activity");
        long Fuel(bool team){var world=new IndustrialWorld();world.Register(1,Point(-1000));world.EnableMiningWorkflow();var excavator=Machine(world,"excavator",0,-7);excavator.input.Add("fuel",200);var output=Machine(world,"store",300);output.input.capacity=100000;var dirt=new SurfaceDeposit{id=world.AllocateId(),pose=Point(0),remaining=new MaterialLot{litres=1000,iron=250}};world.deposits.Add(dirt);IndustrialMachine carrier=null;if(team){carrier=Machine(world,"truck",-20,-20);carrier.input.Add("fuel",200);Assign(world,excavator,dirt.id,output.id,"excavate");Assign(world,carrier,dirt.id,output.id,"transport");}else Assign(world,excavator,dirt.id,output.id,"haul");for(int n=0;n<6000;n++)world.Step();if(output.input.bulk.litres!=1000)throw new Exception("Fuel fixture did not deliver equivalent material");return (team?400:200)-excavator.input.Count("fuel")-(carrier?.input.Count("fuel")??0);}
        long directFuel=Fuel(false),teamFuel=Fuel(true);Check(teamFuel<directFuel,"Equal-material transport uses less fuel with a parked excavator and a dump truck ("+teamFuel+" vs "+directFuel+")");
    }
}
